export default function (pi) {
  let dumps = 0;
  pi.registerTool({
    name: "dump", label: "Dump", description: "Oversized local output",
    parameters: { type: "object", properties: {} },
    async execute() {
      const sizes = [600000];
      const chars = sizes[Math.min(dumps++, sizes.length - 1)];
      return { content: [{ type: "text", text: `DUMP_HEAD ${"x".repeat(chars)} DUMP_TAIL` }, ...[{ type: "image", mimeType: "image/png", data: "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a0ioAAAAASUVORK5CYII=" }]], details: {}, terminate: false };
    },
  });
}
